/* Vision Exchange, OSM way 368005267. Original procedural geometry from
 * the OSM outline and Design Link / Sim Lian photographs; no image textures.
 * The two glass wings stand above the fifth-storey landscaped terrace.
 */
{
const {register,scale,out,rect}=SGJE;
// Own measured registration height; shared catalogue is regenerated by the lead.
// Roof p90 excludes temporary construction cranes in the older references.
SGJE.data.vision_exchange.height=122.1;
SGJE.data.vision_exchange.height_source='Reference roof p90, cranes excluded (image-only metadata)';
register('vision_exchange','Vision Exchange','Vision Exchange',100,(b,D)=>{
 const P=D.parts[0].p,a=.55,c=Math.cos(a),s=Math.sin(a);
 const pt=(u,v)=>[u*c-v*s,u*s+v*c];
 const plate=(u0,u1,v0,v1)=>[pt(u0,v0),pt(u1,v0),pt(u1,v1),pt(u0,v1)];
 const box=(u,y,v,w,h,d,col,mode=0)=>{const q=pt(u,v);b.box(q[0],y,q[1],w,h,d,col,-a,mode);};
 // Four occupied podium levels: transparent shops and offices below the
 // staggered silver/charcoal perforated parking-deck screen.
 b.prism(P,-.6,22.6,'#465359');
 b.facade(out(P,.06),.6,8.0,3.7,2.65,'#48676b','#909fa1',.24);
 b.band(out(P,.15),7.95,.35,'#b8c1bd');
 const screen=out(P,.18);
 screen.forEach((p,i)=>{const q=screen[(i+1)%screen.length],dx=q[0]-p[0],dz=q[1]-p[1],n=Math.max(1,Math.round(Math.hypot(dx,dz)/2.0));
  for(let j=0;j<n;j++)for(let f=0;f<4;f++){
   const t=(j+.035)/n,u=(j+.965)/n,y=8.4+f*3.5,cols=['#bcc5c6','#798a90','#43545d','#98a6ab'];
   const color=cols[(j*7+f*11+i*3)%cols.length];
   const y0=y+((j+i)%3===0?.5:0),y1=Math.min(22.4,y+3.35+((j+i)%3===1?.35:0));
   b.quad(color,[p[0]+dx*t,y0,p[1]+dz*t],[p[0]+dx*u,y0,p[1]+dz*u],[p[0]+dx*u,y1,p[1]+dz*u],[p[0]+dx*t,y1,p[1]+dz*t]);
  }
 });
 b.cap(P,22.65,'#a5afa5');b.rim(P,23.1,'#c5cfca',.3);
 // Narrow planted and paved ribbons visible around the recessed sky lobby.
 b.garden(plate(-80,-50,-8,14),22.72,false);
 for(const [u,v]of [[-73,-3],[-65,8],[-56,-2]]){const q=pt(u,v);b.tree(q[0],22.75,q[1],.52);}
 const south=plate(-45,68,16.0,19.2);b.garden(south,22.72,false);
 for(let u=-39;u<69;u+=14){const q=pt(u,17.6);b.tree(q[0],22.75,q[1],.52);}
 for(let u=-35;u<69;u+=24){box(u,22.75,15.9,9,.12,2,'#b99b74');box(u,22.9,17.6,5,.45,1.1,'#b6bba6');}
 // Open terrace floor under the projecting office volume, with rectangular
 // piers and dark recessed lift-lobby glazing.
 b.prism(plate(-43,69,-5,9),22.7,25.6,'#284147',2);
 for(let u=-44;u<74;u+=15)for(const v of [-7,14])box(u,22.7,v,1.15,3.5,1.15,'#a0aca9');
 // Reference max 144.2 m is a temporary construction crane; the p90 roof
 // measurement 122.1 m is used for the completed building.
 const roof=122.1,lo=26.2,hi=119.8;
 // Separate wings create the fine full-height vertical joint apparent in
 // the developer's aerial photo. The north edge follows the tapered site.
 // Top-view roof corners, cross-checked against the completed aerial photo,
 // place the northwest end well inside the full-length podium. The slab is
 // approximately 119 m long and 23 m deep, not the full 164 m podium length.
 const wings=[[-45,13.5],[14.9,74]];
 for(const [l,r]of wings){
  const n=u=>-8.5;
  const T=[pt(l,n(l)),pt(r,n(r)),pt(r,14.8),pt(l,14.8)];
  b.prism(T,lo,hi,'#245061',2);
  b.facade(out(T,.025),lo,hi,(hi-lo)/20,1.62,'#3b7389','#72949d',.15);
  // Narrow transom at mid-storey, matching the closely spaced horizontal
  // glazing grid rather than thick concrete slab edges.
  for(let f=0;f<20;f++)b.rim(out(T,.065),lo+(f+.5)*(hi-lo)/20,'#486b79',.09);
  b.cap(T,hi+.05,'#b5c0bf');b.rim(T,hi+.35,'#899c9e',.28);
  const R=scale(T,.91);b.cap(R,hi+.11,'#c2ccca');
  // Low rooftop maintenance rails and screened plant stay below the parapet.
  const inner=scale(T,.82);b.rim(inner,roof-.9,'#b3c1c0',.12);
  for(let u=l+6;u<r-3;u+=8)box(u,hi+.18,-2.5,4.8,1.2,4.5,'#a4b2b3');
  b.rim(out(T,-.9),roof-.15,'#adbcbc',.13);
 }
 b.prism(plate(13.5,14.9,-8.5,14.8),lo,hi,'#152e3c',2);
 // The central sky-garden pavilion and modest entrance awnings are built
 // into the podium; no railway or neighbouring geometry is added.
 box(-29,22.8,11.0,10,3.0,6,'#48545b');
 box(46,22.8,15.0,13,.25,5,'#c0ccc4');
 for(const u of [-60,-27,20,54]){box(u,4.4,20.3,9,.2,2.8,'#a3b1ad');box(u,3.7,19.4,4,.45,.12,'#dfd6b4',2);}
});
}
